mapper.sql:
${params.authSql}

    and mn.Te_Id = #{params.teId}


    and mn.P_Id=#{params.pId}


    and  mn.State=#{params.state}


    and INSTR(mn.P_Build_Model,#{params.pBuildModel})


    and INSTR(mn.P_Type,#{params.pType})


    and INSTR(mn.P_Imp_Company,#{params.pImpCompany})


    and INSTR(dp.D_Name,#{params.pCompetentDepartmentName})


    
        
            and likePname(#{params.pName},mn.P_Id)=true
        
        
            and likeCname(#{params.pConstructionUnitName},c1.C_Id)=true
        
    
    
        
            and INSTR(mn.P_Name,#{params.pName})
        
        
            and INSTR(c1.C_Name,#{params.pConstructionUnitName})

mapper.select:
select (b.fcdMoney-b.faDemand) as balanceAmt, (b.fcdMoney-b.payApply) as payBalanceAmt, b.* from ( select (case when fcdAmt is null then 0 else fcdAmt end ) as fcdMoney, (case when faAmt is null then 0 else faAmt end ) as faDemand, (case when payAmt is null then 0 else payAmt end ) as payApply, a.* from ( select mn.P_Id as pId, mn.P_Name as pName, mn.P_Use_Unit as pUseUnit, mn.P_Build_Model as pBuildModel, mn.P_Type as pType, mn.P_Imp_Company as pImpCompany, mn.P_Create_Time as pCreateTime, dp.D_Name as pCompetentDepartmentName, c1.C_Name as pConstructionUnitName, (select max(fcd.Fcd_Batch_No) from Fund_Collection_Details fcd where fcd.P_Id=mn.P_Id and fcd.State=7 ) as fcdBatchNo, (select SUM(fcd.Fcd_Money) from Fund_Collection_Details fcd where fcd.P_Id=mn.P_Id and fcd.State=7) as fcdAmt, (select count(*) from Fund_Appropriation fa where fa.P_Id=mn.P_Id and fa.State=7 ) as faBatchNo, (select SUM(fa.Fa_Demand) from Fund_Appropriation fa where fa.P_Id=mn.P_Id and fa.State=7) as faAmt, (select count(*) from Con_Pay p where p.P_Id=mn.P_Id and p.Pay_State=7) as conPayBatchNo, (select sum(p.Pay_Apply) from Con_Pay p where p.P_Id=mn.P_Id and p.Pay_State=7) as payAmt from Pre_Project mn left join SYS_Department dp on dp.D_Id = mn.P_Competent_Department left join SYS_Company c1 on c1.C_Id = mn.P_Construction_Unit
) a ) b
order by ${params.sortSideFiled} ${params.sortType}
order by pCreateTime DESC

select ( select SUM(P_Inv_Total) from Pre_Project where P_Id in( select mn.P_Id from Fund_Collection_Details mn left join Pre_Project pro on pro.P_Id = mn.P_Id left join Fund_Appropriation fa on fa.id = mn.Fa_Id left join SYS_Department dp on dp.D_Id = pro.P_Competent_Department left join SYS_Company c1 on c1.C_Id = pro.P_Construction_Unit
)) as pInvTotalSum, (select sum(mn.Fcd_Money) from Fund_Collection_Details mn left join Pre_Project pro on pro.P_Id = mn.P_Id left join Fund_Appropriation fa on fa.id = mn.Fa_Id left join SYS_Department dp on dp.D_Id = pro.P_Competent_Department left join SYS_Company c1 on c1.C_Id = pro.P_Construction_Unit
) as fcdMoneySum

mapper.sql:
${params.authSql}

    and mn.Te_Id = #{params.teId}


    and mn.P_Id=#{params.pId}


    and mn.State=#{params.state}


    and pro.P_Build_Model=#{params.pBuildModel}


    
        
            and likePname(#{params.pName},pro.P_Id)=true
        
        
            and pro.P_Name like concat('%',#{params.pName},'%')
        
    


    and INSTR(mn.Create_Uname,#{params.createUname})

mapper.select:
select c1.C_Name as pConstructionUnitName, c2.C_Name as pAgentConstructionUnitName, c3.C_Name as pDesignAndConstructionIntegrationUnitName, d.D_Name as pCompetentDepartmentName, (select sum(Fcd_Money) from Fund_Collection_Details where P_Id=proj.P_Id and State=7) as fcdMoneySum, proj.* from Pre_Project proj left join SYS_Company c1 on c1.C_Id=proj.P_Construction_Unit left join SYS_Company c2 on c2.C_Id=proj.P_Agent_Construction_Unit left join SYS_Company c3 on c3.C_Id=proj.P_Design_And_Construction_Integration_Unit left join SYS_Department d on proj.P_Competent_Department=d.D_Id
and proj.Te_Id = #{params.teId}
and proj.P_Id=#{params.pId}
and proj.P_Build_Model=#{params.pBuildModel}
and proj.P_Type=#{params.pType}
and INSTR(c1.C_Name,#{params.pConstructionUnitName})
and INSTR(proj.P_Imp_Company,#{params.pImpCompany})
and INSTR(d.D_Name,#{params.pCompetentDepartmentName})
and likePname(#{params.pName},proj.P_Id)=true
and INSTR(proj.P_Name,#{params.pName})
and proj.P_Id in (select mn.P_Id from Fund_Collection_Details mn ${params.authSql})
